constraints:
1 ≤ A ≤ 10^{5}

expected time complexity: O( sqrt(A) )
expected auxiliary space: O(1)

standard_solution_code:
import math

class Solution:

	def rectangleCount(self, A):
		(lim, c) = (int(math.sqrt(A)), 0)
		for i in range(1, lim + 1):
			if A % i == 0:
				t = A // i
				if i % 2 == 0 and t % 2 == 0:
					if i == t:
						c += 1
				else:
					c += 1
		return c
